import Model from 'flarum/common/Model';
export const FREQUENCIES = ['immediately', 'hourly', 'daily', 'weekly'];
export default class SavedSearch extends Model {
  query() {
    return Model.attribute('query').call(this);
  }
  filters() {
    return Model.attribute('filters').call(this);
  }
  frequency() {
    return Model.attribute('frequency').call(this);
  }
  createdAt() {
    return Model.attribute('createdAt', Model.transformDate).call(this);
  }
  lastNotifiedAt() {
    return Model.attribute('lastNotifiedAt', Model.transformDate).call(this);
  }
}
flarum.reg.add('ramon-saved-searches', 'common/models/SavedSearch', SavedSearch);